{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "중형 이상 관광버스 관광버스 주차구획 기본요금이 같은 급지 승용차 한 칸 요금의 몇 배인지, 두 시간 안에 나가면 무조건 반값인지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "관광버스 주차장 1구획의 주차요금은 해당 급지 공영주차장 승용차 1구획 주차요금의 2배로 한다. 따라서 중형 이상 관광버스(자동차관리법시행규칙 별표1에 의한 중형이상의 승합자동차)의 관광버스 주차구획 기본요금은 같은 급지 승용차 한 칸 요금의 2배이다.",
          "b_ids": "주차장:별표1#비고10"
        },
        {
          "a_text": "두 시간 안에 나가면 무조건 반값인 것은 아니다. 시장은 최초 2시간 이내 입출차가 주차관리자동화시스템(주차요금결제애플리케이션)에 의해 확인되는 경우에 해당 주차요금의 100분의 50 범위 안에서 할인할 수 있을 뿐이며, 이는 의무적·자동 반값이 아니라 시장의 재량 할인이고 할인 폭도 100분의 50 범위 이내이다.",
          "b_ids": "주차장:별표1#비고10"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
